import { ArrowRight, Clock } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import DisplayFrame from './DisplayFrame';
import { useLocalizedPath } from '../i18n/paths';

/** Grid card for a guide or blog article: image on top, tag, title, blurb. */
export default function ArticleCard({ article, compact = false }) {
  const { t } = useTranslation('edb');
  const localize = useLocalizedPath();
  const { path, title, description, tag, readTime, card, cardWidth, cardHeight, cardFullscreen, type } = article;
  const cta = compact ? t('articleCard.readCompact') : type === 'guide' ? t('articleCard.readGuide') : t('articleCard.readArticle');
  const cardImg = card && (
    <img
      src={card}
      alt=""
      width={cardWidth || undefined}
      height={cardHeight || undefined}
      loading="lazy"
      decoding="async"
      className="absolute inset-0 w-full h-full object-cover object-top transition-transform duration-500 group-hover:scale-[1.04]"
    />
  );
  return (
    <a
      href={localize(path)}
      className="group flex flex-col overflow-hidden rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-800 hover:border-sky-400 dark:hover:border-sky-500 hover:shadow-lg transition-all duration-200"
    >
      {card && (
        cardFullscreen ? (
          <div className="p-3 bg-slate-100 dark:bg-slate-900">
            <DisplayFrame>{cardImg}</DisplayFrame>
          </div>
        ) : (
          <div className="relative aspect-[16/9] overflow-hidden bg-slate-100 dark:bg-slate-900">{cardImg}</div>
        )
      )}
      <div className={`flex flex-col flex-1 ${compact ? 'p-4' : 'p-5'}`}>
        <div className="flex items-center gap-2 mb-2 flex-wrap">
          <span className="text-[11px] font-semibold px-2.5 py-0.5 rounded-full bg-sky-100 dark:bg-sky-900/40 text-sky-700 dark:text-sky-300">{tag}</span>
          {readTime && (
            <span className="flex items-center gap-1 text-[11px] text-slate-500 dark:text-slate-400">
              <Clock className="w-3 h-3" />{readTime}
            </span>
          )}
        </div>
        <h3 className={`font-bold text-slate-900 dark:text-white leading-snug mb-2 group-hover:text-sky-600 dark:group-hover:text-sky-400 transition-colors ${compact ? 'text-sm' : 'text-base'}`}>
          {title}
        </h3>
        {!compact && description && (
          <p className="text-sm text-slate-600 dark:text-slate-300 leading-relaxed mb-3 line-clamp-3">{description}</p>
        )}
        <span className="inline-flex items-center gap-1 text-xs font-semibold text-sky-700 dark:text-sky-300 mt-auto">
          {cta} <ArrowRight className="w-3.5 h-3.5" />
        </span>
      </div>
    </a>
  );
}
